// SigScrub-Cont - bit-rot detection demo
var crypto = require("crypto");
function sum(b) { return crypto.createHash("sha256").update(b).digest("hex"); }
var data = Buffer.from("important payload 12345");
var stored = sum(data);
data[5] = data[5] ^ 0x01; // silent bit flip
var now = sum(data);
console.log("System: SigScrub | Checksum: SHA-256 per extent");
console.log("Stored: " + stored.slice(0, 16) + "...");
console.log("Current:" + now.slice(0, 16) + "...");
console.log(stored === now ? "CLEAN" : "BIT-ROT DETECTED -> quarantine + repair from mesh replica copy");

